events.command:
/bin/bash -lc 'KEY=$(cat "$GALAXY_API_KEY_FILE"); curl -s -H "x-api-key: $KEY" "$GALAXY_URL/api/tools/toolshed.g2.bx.psu.edu%2Frepos%2Fiuc%2Fextract_genomic_dna%2FExtract%20genomic%20DNA%201%2F3.0.3%2Bgalaxy3?io_details=true" | python3 -c '"'import sys,json; d=json.load(sys.stdin); opts=[]
def walk(x):
    if isinstance(x,dict):
        if x.get(\"name\")==\"reference_genome\" and isinstance(x.get(\"options\"),list):
            for o in x[\"options\"]: opts.append(o[0])
        for v in x.values(): walk(v)
    elif isinstance(x,list):
        for v in x: walk(v)
walk(d); print(\"count\",len(opts)); print([o for o in opts if \"danRer\" in o or \"GRCz\" in o or \"zeb\" in o.lower() or \"Zv\" in o][:100])'"
